                return false;
            }
            if (!batch.SerializeFloat(ref value.Pitch))
            {
                return false;
            }
            {
                // 8 bits read as 1 word(s): one bounds check per word, one error test
                ulong c0 = 0;
                batch.SerializeBits64(ref c0, 8);
                if (!batch.Ok)
                {
                    return false;
                }
                ulong v0 = c0 & 0x1UL;
                value.Fire = v0 != 0UL;
                ulong v1 = (c0 >> 1) & 0x1UL;
                value.AltFire = v1 != 0UL;
                ulong v2 = (c0 >> 2) & 0x1UL;
                value.Boost = v2 != 0UL;
                ulong v3 = (c0 >> 3) & 0x1UL;
                value.Brake = v3 != 0UL;
                ulong v4 = (c0 >> 4) & 0x1UL;
                value.Aim = v4 != 0UL;
                ulong v5 = (c0 >> 5) & 0x1UL;
                value.LockOn = v5 != 0UL;
                ulong v6 = (c0 >> 6) & 0x1UL;
                value.Zoom = v6 != 0UL;
                ulong v7 = (c0 >> 7) & 0x1UL;
                value.Ping = v7 != 0UL;
            }
            return true;
        }

